public class Solution {
    public void setZeroes(int[][] matrix) {
        if (matrix == null || matrix.length == 0)
            throw new IllegalArgumentException("Invalid input");

        int rows = matrix.length;
        int cols = matrix[0].length;

        // Step 1: Identify every nested if-else chain inside the method.
        boolean firstRow = false, firstCol = false;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!matrix[i][j]) continue;

                // Step 2: For each nested condition, move it to the method top as a separate if.
                if (i == 0) firstRow = true;
                if (j == 0) firstCol = true;

                matrix[i][0] = 0;
                matrix[0][j] = 0;
            }
        }

        // Step 3: Invert the condition (check the INVALID state, not the valid one).
        for (int i = 1; i < rows; i++) {
            if (!matrix[i][0]) continue;

            for (int j = 1; j < cols; j++) {
                matrix[i][j] = 0;
            }
        }

        // Step 4: Return or throw immediately on the invalid state.
        if (firstRow) {
            for (int j = 0; j < cols; j++)
                matrix[0][j] = 0;
        }

        if (firstCol) {
            for (int i = 0; i < rows; i++)
                matrix[i][0] = 0;
        }
    }
