    private static boolean binarySearch(int[] nums, int left, int right, int target) {
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) return true;

            // Handle duplicates
            if (nums[left] == nums[mid]) {
                left++;
                continue; // Skip duplicate elements to avoid infinite loop
            }

            // Determine which part of the array is sorted and adjust search range accordingly
            boolean isLeftSorted = nums[left] < nums[mid];
            if ((isLeftSorted && target >= nums[left] && target <= nums[mid]) ||
                (!isLeftSorted && (target > nums[mid] || target <= nums[right]))) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        return false;
    }
}

