    private void initializeDictionaryAndQueue(String beginWord, String endWord, Set<String> dict, Queue<String> queue, Map<String, Integer> distance) {
        dict.remove(beginWord); // Remove the start word from the dictionary
        dict.add(endWord);

        for (String word : dict) {
            if (!word.equals(beginWord)) { // Initialize distances to infinity except for beginWord
                distance.put(word, Integer.MAX_VALUE);
            }
        }

        queue.offer(beginWord);
        distance.put(beginWord, 0); // Set the start word's distance to zero

        while (!queue.isEmpty()) {
            String current = queue.poll();
            if (current.equals(endWord)) {
                break;
            }
            for (String neighbor : neighbors(current)) {
                if (!dict.contains(neighbor)) {
                    continue;
                }
                int newDistance = distance.get(current) + 1;
                if (newDistance < distance.getOrDefault(neighbor, Integer.MAX_VALUE)) { // Update the shortest path
                    distance.put(neighbor, newDistance);
                    queue.offer(neighbor);
                }
            }
        }
    }

    private void backtrack(String current, String endWord, List<String> path, Map<String, Integer> distance) {
        if (current.equals(endWord)) {
            result.add(new ArrayList<>(path));
            return;
        }
        for (String next : neighbors(current).stream()
 .filter(neighbor -> distance.get(next) == distance.get(current) + 1)
 .collect(Collectors.toList())) { // Filter by the shortest path
            path.add(next);
            backtrack(next, endWord, path, distance);
            path.remove(path.size() - 1);
        }
    }

    private List<String> neighbors(String word) {
        List<String> result = new ArrayList<>();
        char[] chars = word.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            char original = chars[i];
            for (char j = 'a'; j <= 'z'; j++) {
                if (j == original) {
                    continue;
                }
                chars[i] = j;
                result.add(new String(chars));
            }
            chars[i] = original;
        }
        return result;
    }
