        if (head == null || head.next == null) return head;

        ListNode dummy = new ListNode(0);
        ListNode cur, temp;

        while (head != null) {
            insert(head.val, dummy);
            head = head.next;
        }

        return dummy.next;
    }

    private void insert(int val, ListNode dummy) {
        ListNode prev = dummy;
        ListNode curr = dummy.next;

        while (curr != null && curr.val < val) {
            prev = curr;
            curr = curr.next;
        }

        temp = new ListNode(val);
        prev.next = temp;
        temp.next = curr;
    }
}

