    }

  private int computeShortestDistance(String[] wordsDict, String word1, String word2) {
        int idx1 = -1, idx2 = -1;
        for (int i = 0; i < wordsDict.length; i++) {
            if (word1.equals(wordsDict[i])) idx1 = i;
            if (word2.equals(wordsDict[i])) idx2 = i;
            if (idx1 != -1 && idx2 != -1)
                return Math.abs(idx1 - idx2);
        }
        throw new IllegalArgumentException("Words not found in the list");
    }

  private int computeShortestDistance(String[] words, String word1, String word2) {
