import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<List<Integer>> getFactors(int n) {
        if (n <= 1) return new ArrayList<>();

        List<List<Integer>> result = new ArrayList<>();
        helper(n, 2, new ArrayList<>(), result);
        return result;
    }

    private void helper(int n, int start, List<Integer> path, List<List<Integer>> result) {
        for (int i = start; i <= Math.sqrt(n); i++) {
            if (n % i == 0) {
                path.add(i);
                path.add(n / i);
                result.add(new ArrayList<>(path));
                path.remove(path.size() - 1);
                helper(n / i, i, path, result);
                path.remove(path.size() - 1);
            }
        }

        if (n > 1) {
            List<Integer> singleElementList = new ArrayList<>();
            singleElementList.add(n);
            result.add(singleElementList);
        }
    }
}
